SELECT 
  FROM APP_USER u
 WHERE u.USER_ID = #{userId}

mapper.update:
UPDATE APP_USER
   SET ACCOUNT_STATUS_CODE = 'LOCKED', LOCK_REASON = #{reason}, LOCKED_AT = #{now}, UPDATED_AT = #{now}
 WHERE USER_ID = #{userId}
   AND ACCOUNT_STATUS_CODE <> 'WITHDRAWN'

UPDATE APP_USER
   SET ACCOUNT_STATUS_CODE = 'ACTIVE', LOGIN_FAIL_COUNT = 0, LOCK_REASON = NULL, LOCKED_AT = NULL, UPDATED_AT = #{now}
 WHERE USER_ID = #{userId}
   AND ACCOUNT_STATUS_CODE <> 'WITHDRAWN'

