mapper.update:
UPDATE APP_USER
   SET PASSWORD_HASH = #{passwordHash}, PASSWORD_CHANGE_REQUIRED_YN = 'Y', ACCOUNT_STATUS_CODE = 'ACTIVE',
       LOGIN_FAIL_COUNT = 0, LOCK_REASON = NULL, LOCKED_AT = NULL, UPDATED_AT = #{now}
 WHERE USER_ID = #{userId}
   AND ROLE_CODE = 'ROLE_ADMIN'
   AND ACCOUNT_STATUS_CODE <> 'WITHDRAWN'

UPDATE APP_USER
   SET PASSWORD_HASH = #{passwordHash}, PASSWORD_CHANGE_REQUIRED_YN = 'N', UPDATED_AT = #{now}
 WHERE USER_ID = #{userId}
   AND ACCOUNT_STATUS_CODE <> 'WITHDRAWN'
